<?php
require __DIR__.'/bootstrap.php';
$tests=[];
function test($name,$fn){global $tests;$tests[$name]=$fn;}
function check($ok,$message='Assertion failed'){if(!$ok)throw new RuntimeException($message);}
function eq($actual,$expected,$message=''){check($actual===$expected,$message?:'Expected '.substr(var_export($expected,true),0,300).', got '.substr(var_export($actual,true),0,300));}
test('Forced closure wins over the weekly schedule',function(){ $GLOBALS['options']['ttos_site_content']['opening_times']['override']='force_closed';eq(TTOS_Operations::ordering_state('delivery')['open'],false);});
test('Forced closure also disables configured preorders',function(){ $GLOBALS['options']['ttos_operations_settings']=['checkout'=>['preorder_enabled'=>'1']];$GLOBALS['options']['ttos_site_content']['opening_times']['override']='force_closed';eq(TTOS_Operations::can_accept_menu_orders(),false);});
test('Temporary closure disables preorders',function(){ $GLOBALS['options']['ttos_operations_settings']=['checkout'=>['preorder_enabled'=>'1']];$GLOBALS['options']['ttos_site_content']['opening_times']['temporary_closure']='1';eq(TTOS_Operations::can_accept_menu_orders(),false);});
test('Preorder-only never becomes immediate ordering',function(){ $GLOBALS['options']['ttos_site_content']['opening_times']['override']='preorder';$s=TTOS_Operations::ordering_state('delivery');eq($s['open'],false);eq($s['preorder_required'],true);});
test('Dashboard override writes the actual schedule and preserves hours',function(){ $before=ttos_get_opening_hours()['days'];TTOS_Dashboard_REST::toggle_open(new WP_REST_Request(['override'=>'force_closed']));eq(ttos_get_opening_hours()['override'],'force_closed');eq(ttos_get_opening_hours()['days'],$before);});
test('Dashboard pause reaches existing checkout protection',function(){TTOS_Dashboard_REST::set_pause(new WP_REST_Request(['paused'=>true]));eq(TTOS_Production::block_add_to_cart_if_paused(true),false);TTOS_Production::block_checkout_if_paused();check(count($GLOBALS['notices'])>0);});
test('Dashboard snapshot reads the production pause',function(){ $GLOBALS['options']['ttos_production_settings']=['pause_enabled'=>'1'];$s=TTOS_Dashboard_REST::snapshot(new WP_REST_Request())->data;eq($s['paused'],true);eq($s['ordering_open'],false);});
test('Unpause preserves unrelated production settings',function(){ $GLOBALS['options']['ttos_production_settings']=['pause_enabled'=>'1','retention_delay_days'=>'47','handover_notes'=>'keep'];TTOS_Dashboard_REST::set_pause(new WP_REST_Request(['paused'=>false]));eq(TTOS_Production::get('pause_enabled'),'0');eq(TTOS_Production::get('retention_delay_days'),'47');eq(TTOS_Production::get('handover_notes'),'keep');});
test('No service windows means no invented scheduled slots',function(){ foreach($GLOBALS['options']['ttos_site_content']['opening_times']['days'] as &$d)$d['closed']='1';unset($d);$s=TTOS_Operations::ordering_state('delivery');$slots=invoke_private('TTOS_Operations','time_slot_options',TTOS_Operations::get('checkout'),'delivery',$s);eq(count(array_filter(array_keys($slots),fn($v)=>$v!==''&&$v!=='asap')),0);});
test('Service windows have exact minute boundaries',function(){ $w=invoke_private('TTOS_Operations','service_windows','delivery',1);foreach($w as $row){eq($row['start']%60,0);eq($row['end']%60,0);}});
test('Reject invalid delivery flag without partially updating',function(){ $before=TTOS_Settings::get();$r=TTOS_Dashboard_REST::patch_settings(new WP_REST_Request(['trading.min_order'=>'20','trading.delivery_enabled'=>'banana']));eq($r->status,400);eq(TTOS_Settings::get(),$before);});
test('Boolean flags normalise to the existing string schema',function(){TTOS_Dashboard_REST::patch_settings(new WP_REST_Request(['trading.delivery_enabled'=>true,'trading.collection_enabled'=>false]));eq(TTOS_Settings::get('trading','delivery_enabled'),'1');eq(TTOS_Settings::get('trading','collection_enabled'),'0');});
test('Negative order minimum is rejected',function(){eq(TTOS_Dashboard_REST::patch_settings(new WP_REST_Request(['trading.min_order'=>'-10']))->status,400);});
test('Nested setting values are rejected',function(){eq(TTOS_Dashboard_REST::patch_settings(new WP_REST_Request(['trading.min_order'=>['bad']]))->status,400);});
test('CRM includes customers beyond the newest 500 orders',function(){for($i=1;$i<=650;$i++)$GLOBALS['orders'][]=new FixtureOrder($i,'customer'.$i.'@example.test');$a=invoke_private('TTOS_Admin','customer_snapshot_enhanced',300);eq(count($a),650);check(isset($a['customer1@example.test']));});
test('CRM totals are identical for dashboard and campaign calls',function(){for($i=1;$i<=650;$i++)$GLOBALS['orders'][]=new FixtureOrder($i,'repeat@example.test');$a=invoke_private('TTOS_Admin','customer_snapshot_enhanced',300);$b=invoke_private('TTOS_Admin','customer_snapshot_enhanced',500);eq($a,$b);eq($a['repeat@example.test']['orders'],650);});
test('CRM excludes unpaid orders from spend',function(){ $GLOBALS['orders']=[new FixtureOrder(1,'paid@example.test','10.00'),new FixtureOrder(2,'paid@example.test','80.00','on-hold','0.00','GBP',false),new FixtureOrder(3,'paid@example.test','70.00','pending','0.00','GBP',false)];$a=invoke_private('TTOS_Admin','customer_snapshot_enhanced',300);eq((float)$a['paid@example.test']['total'],10.0);});
test('CRM subtracts recorded refunds',function(){ $GLOBALS['orders']=[new FixtureOrder(1,'refund@example.test','10.00','completed','4.00')];$a=invoke_private('TTOS_Admin','customer_snapshot_enhanced',300);eq((float)$a['refund@example.test']['total'],6.0);});
test('Legacy kitchen status does not erase a native paid date',function(){ $GLOBALS['orders']=[new FixtureOrder(1,'legacy@example.test','10.00','ttos-accepted')];$a=invoke_private('TTOS_Admin','customer_snapshot_enhanced',300);eq((float)$a['legacy@example.test']['total'],10.0);});
test('Different currencies are not added into one money total',function(){ $GLOBALS['orders']=[new FixtureOrder(1,'money@example.test','10.00'),new FixtureOrder(2,'money@example.test','20.00','completed','0.00','USD')];$a=invoke_private('TTOS_Admin','customer_snapshot_enhanced',300);eq((float)$a['money@example.test']['total'],10.0);});
test('REST unsubscribe clears the permission used by the sender',function(){ $GLOBALS['users'][7]=(object)['ID'=>7,'user_email'=>'person@example.test'];$GLOBALS['meta'][7]['_ttos_retention_uid']='fixture-uid';$GLOBALS['options']['ttos_customer_profiles']=['person@example.test'=>['marketing_ok'=>'1','internal_notes'=>'keep']];$r=TTOS_Retention::rest_unsubscribe(new WP_REST_Request(['uid'=>'fixture-uid']));eq($r->status,200);eq(invoke_private('TTOS_Production','customer_marketing_opt_in','person@example.test'),false);eq(get_option('ttos_customer_profiles')['person@example.test']['internal_notes'],'keep');});
test('Signup link is not advertised as a completed connection',function(){ $p=TTOS_OAuth_Connectors::status_payload();check($p['xero']['message']!=='Ready to connect.');eq($p['xero']['connected'],false);});
test('Empty retry queues do not write noisy success logs',function(){TTOS_Features::retry_queue_handler();eq(get_option('ttos_integration_log',[]),[]);});
test('Accounting invalid dates return an error, not an exception',function(){ $r=TTOS_Accounting::rest_export(new WP_REST_Request(['provider'=>'generic','from'=>'not-a-date','to'=>'2026-09-30']));eq($r->status,400);});
test('Opening boundaries use UTC instants, not offset timestamps',function(){foreach($GLOBALS['options']['ttos_site_content']['opening_times']['days'] as &$d){$d['open']='17:00';$d['close']='22:00';}unset($d);$t=strtotime('2026-09-30T15:59:59Z');eq(TTOS_Operations::ordering_state('delivery',$t)['open'],false);eq(TTOS_Operations::ordering_state('delivery',$t+1)['open'],true);eq(TTOS_Operations::ordering_state('delivery',strtotime('2026-09-30T21:00:00Z'))['open'],false);});
test('Overnight opening uses the previous local day',function(){foreach($GLOBALS['options']['ttos_site_content']['opening_times']['days'] as &$d){$d['open']='18:00';$d['close']='02:00';}unset($d);eq(TTOS_Operations::ordering_state('delivery',strtotime('2026-10-01T00:30:00Z'))['open'],true);eq(TTOS_Operations::ordering_state('delivery',strtotime('2026-10-01T01:00:00Z'))['open'],false);});
test('Winter schedule does not retain the summer offset',function(){foreach($GLOBALS['options']['ttos_site_content']['opening_times']['days'] as &$d){$d['open']='17:00';$d['close']='22:00';}unset($d);eq(TTOS_Operations::ordering_state('delivery',strtotime('2026-11-04T16:59:59Z'))['open'],false);eq(TTOS_Operations::ordering_state('delivery',strtotime('2026-11-04T17:00:00Z'))['open'],true);});
test('Disabled collection cannot be opened by override',function(){$GLOBALS['options']['ttos_settings']=['trading'=>['collection_enabled'=>'0']];$GLOBALS['options']['ttos_site_content']['opening_times']['override']='force_open';eq(TTOS_Operations::ordering_state('collection')['open'],false);});
test('Old pause setting works only until canonical setting exists',function(){$GLOBALS['options']['ttos_ordering_paused']='1';eq(TTOS_Production::is_paused(),true);$GLOBALS['options']['ttos_production_settings']=['pause_enabled'=>'0'];eq(TTOS_Production::is_paused(),false);});
test('Explicit marketing permission edit can undo a previous opt-out',function(){$GLOBALS['users'][7]=(object)['ID'=>7,'user_email'=>'person@example.test'];$GLOBALS['meta'][7]['_ttos_retention_opt_out']='1';TTOS_Production::record_marketing_permission('person@example.test',true);eq(TTOS_Production::customer_marketing_opt_in('person@example.test'),true);});
test('Old user opt-out vetoes imported marketing permission',function(){$GLOBALS['users'][7]=(object)['ID'=>7,'user_email'=>'person@example.test'];$GLOBALS['meta'][7]['_ttos_retention_opt_out']='1';$GLOBALS['options']['ttos_customer_profiles']=['person@example.test'=>['marketing_ok'=>'1']];eq(TTOS_Production::customer_marketing_opt_in('person@example.test'),false);});
test('Unknown unsubscribe UID changes no permissions',function(){$GLOBALS['options']['ttos_customer_profiles']=['person@example.test'=>['marketing_ok'=>'1']];$before=$GLOBALS['options'];eq(TTOS_Retention::rest_unsubscribe(new WP_REST_Request(['uid'=>'missing']))->status,404);eq($GLOBALS['options'],$before);});
test('Invalid accounting calendar dates are rejected',function(){eq(TTOS_Accounting::rest_export(new WP_REST_Request(['provider'=>'generic','from'=>'2026-02-30','to'=>'2026-03-02']))->status,400);});
test('Reversed accounting dates are rejected',function(){eq(TTOS_Accounting::rest_export(new WP_REST_Request(['provider'=>'generic','from'=>'2026-10-01','to'=>'2026-09-30']))->status,400);});
test('Dashboard capability remains required',function(){$GLOBALS['permission']=false;eq(TTOS_Dashboard_REST::admin_permission(),false);});
test('Applying profile preserves payment, tax and currency settings',function(){$keys=['woocommerce_currency'=>'EUR','woocommerce_default_country'=>'IE','woocommerce_calc_taxes'=>'yes','woocommerce_prices_include_tax'=>'yes','woocommerce_cod_settings'=>['enabled'=>'no'],'woocommerce_stripe_settings'=>['enabled'=>'yes','testmode'=>'no'],'woocommerce_onboarding_profile'=>['custom'=>'keep']];$GLOBALS['options']=array_merge($GLOBALS['options'],$keys);TTOS_Onboarding::apply_profile();foreach($keys as $k=>$v)eq(get_option($k),$v,$k.' was changed');});
test('Reapplying profile does not add or enable cash gateway',function(){TTOS_Onboarding::apply_profile();eq(get_option('woocommerce_cod_settings'),false);eq(TTOS_WooCommerce::ensure_cod_gateway(['existing']),['existing']);});
test('WooCommerce gateway registry is not intercepted',function(){TTOS_WooCommerce::hooks();foreach($GLOBALS['registered_hooks'] as $h)check($h[0]!=='woocommerce_payment_gateways');});
test('Unavailable native variable product is not converted to simple',function(){$p=new WC_Product_Simple(1);$p->data['type']='variable';$p->save();eq(TTOS_WooCommerce::create_or_update_product(['product_id'=>1,'name'=>'Keep type','price'=>'10']),0);eq($p->data['type'],'variable');});
test('Menu price and feature updates use native product setters',function(){$p=new WC_Product_Simple(1);$p->data['name']='Existing';$p->data['image_id']=44;$p->save();eq(TTOS_WooCommerce::create_or_update_product(['product_id'=>1,'name'=>'Updated','price'=>'12.50','featured'=>true]),1);eq((float)$p->data['regular_price'],12.5);eq($p->data['featured'],true);eq($p->data['image_id'],44);});
test('Availability does not invent tracked stock',function(){$p=new WC_Product_Simple(1);$p->data['manage_stock']=true;$p->data['stock_quantity']=0;$p->data['stock_status']='outofstock';$p->save();TTOS_WooCommerce::set_product_state(1,'available');eq($p->data['stock_quantity'],0);eq($p->data['stock_status'],'outofstock');});
test('Negative menu prices are rejected without saving',function(){$p=new WC_Product_Simple(1);$p->data['name']='Existing';$p->save();eq(TTOS_WooCommerce::create_or_update_product(['product_id'=>1,'name'=>'Changed','price'=>'-1']),0);eq($p->data['name'],'Existing');});
test('Repeated scheduler repair creates no duplicate jobs',function(){TTOS_Features::hooks();$events=$GLOBALS['events'];TTOS_Features::hooks();eq($GLOBALS['events'],$events);});
test('Deactivation removes only owned dispatch jobs',function(){$GLOBALS['events']=['ttos_retry_integrations'=>['time'=>1],'ttos_inventory_daily_reset'=>['time'=>2],'ttos_send_retention_email'=>['time'=>3],'native-woo-task'=>['time'=>4]];TTOS_Activator::deactivate();eq($GLOBALS['events'],['native-woo-task'=>['time'=>4]]);});
test('Administrator is not trapped by an old module key',function(){$GLOBALS['options']['ttos_module_lock_hash']='legacy-hash';eq(invoke_private('TTOS_Admin','modules_unlocked'),true);});
test('Kitchen acceptance preserves native WooCommerce payment status',function(){$o=new FixtureOrder(1,'kitchen@example.test','10','processing');$GLOBALS['orders']=[$o];$r=invoke_private('TTOS_Admin','apply_order_action',1,'ttos-accepted',20);eq($r['ok'],true);eq($o->get_status(),'processing');eq($o->get_meta('_ttos_kitchen_status'),'ttos-accepted');});
test('Kitchen note save never resets the payment status',function(){$o=new FixtureOrder(1,'kitchen@example.test','10','on-hold',0,'GBP',false);$GLOBALS['orders']=[$o];invoke_private('TTOS_Admin','apply_order_action',1,'',0,'Please check');eq($o->get_status(),'on-hold');eq($o->get_meta('_ttos_kitchen_note'),'Please check');});
test('Terminal commerce status overrides stale kitchen metadata',function(){$o=new FixtureOrder(1,'kitchen@example.test','10','refunded');$o->data['_ttos_kitchen_status']='ttos-ready';eq(TTOS_WooCommerce::kitchen_status($o),'refunded');});
test('Package presets never change WooCommerce settings or ordering pause',function(){$GLOBALS['options']['woocommerce_cod_settings']=['enabled'=>'no'];$GLOBALS['options']['ttos_settings']=['modules'=>['printer'=>true]];$GLOBALS['options']['ttos_production_settings']=['pause_enabled'=>'0'];check(TTOS_Packages::apply('ordering'));eq(get_option('woocommerce_cod_settings'),['enabled'=>'no']);eq(TTOS_Production::is_paused(),false);eq(TTOS_Settings::module_enabled('printer'),true);});
test('Package changes require administrator access',function(){$GLOBALS['caps']['manage_options']=false;eq(TTOS_Packages::apply('growth'),false);eq(get_option('ttos_package_profile'),false);});
test('Unknown package is rejected without a write',function(){$before=$GLOBALS['options'];eq(TTOS_Packages::apply('invented'),false);eq($GLOBALS['options'],$before);});
test('Reports use recorded tax rather than an assumed VAT percentage',function(){$GLOBALS['orders']=[new FixtureOrder(1,'tax@example.test','120.00')];$t=strtotime('2026-01-01');$report=TTOS_Analytics::report($t,$t+86400);eq((float)$report['summary']['tax'],1.0);eq((float)$report['summary']['vat_estimate'],1.0);eq($report['summary']['direct_savings_estimate'],null);});
test('Reports exclude unpaid orders and mixed currency totals',function(){$GLOBALS['orders']=[new FixtureOrder(1,'tax@example.test','10.00'),new FixtureOrder(2,'tax@example.test','100.00','on-hold',0,'GBP',false),new FixtureOrder(3,'tax@example.test','200.00','completed',0,'EUR')];$t=strtotime('2026-01-01');$report=TTOS_Analytics::report($t,$t+86400);eq((float)$report['summary']['gross'],10.0);});
test('Report range includes orders created at exact boundary',function(){$o=new FixtureOrder(1,'tax@example.test');$GLOBALS['orders']=[$o];$t=$o->get_date_created()->getTimestamp();eq(count(TTOS_Analytics::orders_between($t,$t)),1);});
test('Cancelled paid orders retain recorded money until actually refunded',function(){$GLOBALS['orders']=[new FixtureOrder(1,'tax@example.test','10.00','cancelled')];$c=invoke_private('TTOS_Admin','customer_snapshot_enhanced');eq((float)$c['tax@example.test']['total'],10.0);});
test('Incomplete follow-up schedules restore once without resetting due time',function(){$GLOBALS['options']['ttos_production_settings']=['retention_enabled'=>'1'];$GLOBALS['options']['ttos_customer_profiles']=['person@example.test'=>['marketing_ok'=>'1']];$due=time()+3600;$GLOBALS['options']['ttos_retention_jobs']=['person@example.test'=>['scheduled_for'=>$due]];TTOS_Production::restore_retention_jobs();eq($GLOBALS['events']['ttos_send_retention_email']['time'],$due);$before=$GLOBALS['events'];TTOS_Production::restore_retention_jobs();eq($GLOBALS['events'],$before);});
test('Unsubscribed follow-ups are not restored',function(){$GLOBALS['options']['ttos_production_settings']=['retention_enabled'=>'1'];$GLOBALS['options']['ttos_retention_jobs']=['person@example.test'=>['scheduled_for'=>time()+3600]];TTOS_Production::restore_retention_jobs();eq($GLOBALS['events'],[]);});
test('Configured modules are not overridden by hidden production locks',function(){$GLOBALS['options']['ttos_settings']=['modules'=>['printer'=>true,'promo_engine'=>true,'allergen_filters'=>true]];eq(TTOS_Settings::module_enabled('printer'),true);eq(TTOS_Settings::module_enabled('promo_engine'),true);eq(TTOS_Settings::module_enabled('allergen_filters'),true);});
test('Unpaid kitchen stages never mark an order paid',function(){$o=new FixtureOrder(1,'kitchen@example.test','10','on-hold',0,'GBP',false);$GLOBALS['orders']=[$o];foreach(['ttos-accepted','ttos-prepping','ttos-ready','ttos-out'] as $stage){invoke_private('TTOS_Admin','apply_order_action',1,$stage);eq($o->get_status(),'on-hold');eq($o->get_date_paid(),null);}eq($o->updates,[]);});
test('Kitchen board does not silently lose order 101',function(){for($i=1;$i<=205;$i++){$o=new FixtureOrder($i,'kitchen@example.test','10','processing');$o->data['_ttos_kitchen_status']='ttos-accepted';$GLOBALS['orders'][]=$o;}$counts=invoke_private('TTOS_Admin','order_board_counts');eq($counts['active'],205);eq($counts['new'],0);});
test('Owner export and profile handlers are not trapped by CRM redirect',function(){$GLOBALS['caps']['manage_options']=false;foreach(['admin-post.php','profile.php','upload.php'] as $page){$GLOBALS['pagenow']=$page;TTOS_Admin::crm_mode_redirect();}});
test('Legacy forced-off flags migrate once without becoming permanent locks',function(){$GLOBALS['options']['ttos_settings']=['modules'=>['printer'=>true,'loyalty'=>true]];invoke_private('TTOS_Activator','migrate_legacy_module_selection','1.3.12');eq(TTOS_Settings::module_enabled('printer'),false);eq(TTOS_Settings::module_enabled('loyalty'),true);$m=TTOS_Settings::modules();$m['printer']=true;TTOS_Settings::update_section('modules',$m);invoke_private('TTOS_Activator','migrate_legacy_module_selection','1.3.12');eq(TTOS_Settings::module_enabled('printer'),true);});
$passed=0;$failed=0;
foreach($tests as $name=>$fn){reset_fixture();try{$fn();echo "PASS $name\n";$passed++;}catch(Throwable $e){echo "FAIL $name: {$e->getMessage()}\n";$failed++;}}
echo "RESULT $passed passed, $failed failed, ".count($tests)." tests\n";exit($failed?1:0);
